import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.Ki30n65y.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}'),c={name:"reference/configuration.md"};function r(i,e,n,s,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>DepGate is configured with environment variables. The names are the same in every production setup: <code>.env</code> in <code>deploy/all-in-one/</code> and <code>deploy/app-only/</code> (each has an <code>.env.example</code> that lists them with explanations), and the ConfigMap <code>depgate-config</code> and Secret <code>depgate-secrets</code> in <code>deploy/kubernetes/</code>. Restart DepGate to apply a change: <code>./3-run.sh</code> with Compose, <code>kubectl rollout restart deployment/depgate</code> on Kubernetes.</p><p>Settings that Security users change in the web interface (repositories, single sign-on, email, webhooks, log streaming, the artifact cache, the registry token lifetime and the gateway security controls) are stored in the database and need no restart.</p><h2 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>GATEWAY_URL</code></td><td>The address people and package clients use, for example <code>https://depgate.example.com</code>. Download links in registry responses are built from it.</td></tr><tr><td><code>JWT_SECRET</code></td><td>Secret that signs sessions and registry tokens. Generate it with <code>openssl rand -hex 32</code> and keep it: changing it signs everyone out and invalidates every registry token.</td></tr><tr><td><code>ADMIN_EMAIL</code></td><td>The first Security account, created on first start on an empty database only. Changing it later does nothing.</td></tr><tr><td><code>ADMIN_PASSWORD</code></td><td>Its initial password, read at that first start only. Change it in the web interface afterwards; both variables may then be removed.</td></tr><tr><td><code>DEPGATE_IMAGE</code>, <code>DEPGATE_VERSION</code></td><td>The image and tag to run (Compose setups; <code>secmods/depgate</code> and the release version). On Kubernetes: <code>images:</code> in <code>kustomization.yaml</code>.</td></tr></tbody></table><h2 id="server-and-https" tabindex="-1">Server and HTTPS <a class="header-anchor" href="#server-and-https" aria-label="Permalink to &quot;Server and HTTPS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>DISABLE_SSL</code></td><td><code>false</code></td><td><code>true</code> serves plain HTTP only, for TLS on your own proxy or load balancer.</td></tr><tr><td><code>TLS_CERT_FILE</code>, <code>TLS_KEY_FILE</code></td><td><code>/certs/tls.crt</code>, <code>/certs/tls.key</code></td><td>Certificate (full chain) and private key, in PEM. Reloaded automatically when the files change.</td></tr><tr><td><code>HTTPS_PORT</code>, <code>HTTP_PORT</code></td><td><code>443</code>, <code>80</code></td><td>Host ports.</td></tr><tr><td><code>HTTP_BIND</code></td><td><code>0.0.0.0</code></td><td>Host address for the HTTP port. <code>127.0.0.1</code> when your proxy runs on the same host.</td></tr><tr><td><code>HTTP_REDIRECT</code></td><td><code>true</code></td><td>With HTTPS on, redirect HTTP to HTTPS. <code>false</code> closes the HTTP port.</td></tr><tr><td><code>TRUST_PROXY</code></td><td><code>1</code> with <code>DISABLE_SSL</code>, otherwise <code>false</code></td><td>Which proxies may set <code>X-Forwarded-For</code>: <code>false</code>, a number of hops, or a list of addresses and CIDR ranges.</td></tr><tr><td><code>UI_URL</code></td><td><code>GATEWAY_URL</code></td><td>The address of the web interface, used in email links and in the Package check link of block responses.</td></tr><tr><td><code>DOCS_URL</code></td><td>none</td><td>The documentation site linked from <strong>Help → Documentation</strong> in the sidebar, for example an internal copy. Unset hides the link.</td></tr><tr><td><code>MANAGEMENT_PORT</code></td><td><code>9464</code> in Docker</td><td>Private port for <code>/metrics</code>, <code>/healthz</code> and <code>/readyz</code>.</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>info</code></td><td><code>debug</code>, <code>info</code>, <code>warn</code> or <code>error</code>.</td></tr><tr><td><code>DEPGATE_INSTANCE_NAME</code></td><td>the host of <code>GATEWAY_URL</code></td><td>The installation&#39;s name in streamed events.</td></tr></tbody></table><h2 id="database-postgresql" tabindex="-1">Database (PostgreSQL) <a class="header-anchor" href="#database-postgresql" aria-label="Permalink to &quot;Database (PostgreSQL)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_HOST</code>, <code>DB_PORT</code></td><td><code>localhost</code>, <code>5432</code></td><td>Server address.</td></tr><tr><td><code>DB_USER</code>, <code>DB_PASSWORD</code>, <code>DB_NAME</code></td><td><code>depgate</code></td><td>Credentials and database.</td></tr><tr><td><code>DB_SSL</code></td><td><code>false</code></td><td>Encrypt the connection.</td></tr><tr><td><code>DB_SSL_CA_FILE</code></td><td>none</td><td>CA certificate (PEM) to verify the server, for example <code>/certs/ca.crt</code>.</td></tr><tr><td><code>DB_POOL_SIZE</code></td><td><code>20</code></td><td>Connections per replica.</td></tr></tbody></table><h2 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>REDIS_URL</code></td><td><code>redis://localhost:6379</code></td><td>Cache and job queues. Use <code>rediss://</code> for TLS; put the password in the URL. Requires <code>maxmemory-policy noeviction</code>.</td></tr><tr><td><code>QUEUE_REDIS_URL</code></td><td><code>REDIS_URL</code></td><td>Optional separate Redis for the job queues.</td></tr><tr><td><code>QUEUE_PREFIX</code></td><td><code>depgate</code></td><td>Key prefix, to share one Redis between several installations.</td></tr><tr><td><code>WORKERS</code></td><td><code>all</code></td><td>Which queues this replica processes: <code>all</code>, <code>none</code>, or a list of <code>webhooks</code>, <code>scheduled</code>, <code>email</code>, <code>monitor</code>.</td></tr></tbody></table><h2 id="outbound-network" tabindex="-1">Outbound network <a class="header-anchor" href="#outbound-network" aria-label="Permalink to &quot;Outbound network&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>NODE_USE_ENV_PROXY</code></td><td><code>1</code> sends outgoing requests through the proxy below.</td></tr><tr><td><code>HTTP_PROXY</code>, <code>HTTPS_PROXY</code></td><td>The outbound proxy, for example <code>http://proxy.example.com:3128</code>.</td></tr><tr><td><code>NO_PROXY</code></td><td>Hosts reached directly: internal registries, webhook endpoints.</td></tr><tr><td><code>NODE_EXTRA_CA_CERTS</code></td><td>Extra CA certificates trusted for outgoing TLS. <code>/certs/ca.crt</code> in Docker.</td></tr></tbody></table><h2 id="authentication-and-email" tabindex="-1">Authentication and email <a class="header-anchor" href="#authentication-and-email" aria-label="Permalink to &quot;Authentication and email&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>UI_SESSION_EXPIRES_IN</code></td><td><code>1h</code></td><td>Browser session lifetime.</td></tr><tr><td><code>INVITE_EXPIRY_HOURS</code></td><td><code>168</code></td><td>How long an invitation link works.</td></tr><tr><td><code>PASSWORD_RESET_EXPIRY_MINUTES</code></td><td><code>60</code></td><td>How long a password reset link works.</td></tr><tr><td><code>LOGIN_FAILURE_LIMIT_PER_EMAIL</code>, <code>LOGIN_FAILURE_LIMIT_PER_IP</code></td><td><code>10</code>, <code>100</code></td><td>Failed password sign-ins per 15 minutes before sign-in waits. <code>0</code> removes the limit.</td></tr><tr><td><code>LOGIN_FAILURE_AUDIT_PER_MINUTE</code></td><td><code>20</code></td><td>Failed sign-ins written to the Audit Log per address and minute; the rest are only counted.</td></tr><tr><td><code>SSO_RATE_LIMIT</code></td><td><code>600</code></td><td>Requests per address and 10 minutes to the single sign-on endpoints. <code>0</code> removes the limit.</td></tr><tr><td><code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_SECURE</code>, <code>SMTP_USER</code>, <code>SMTP_PASSWORD</code>, <code>SMTP_FROM</code></td><td>none</td><td>Mail server. Settings saved under <strong>Settings → Email</strong> take precedence.</td></tr></tbody></table><h2 id="package-check" tabindex="-1">Package check <a class="header-anchor" href="#package-check" aria-label="Permalink to &quot;Package check&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PACKAGE_CHECK_RATE_LIMIT</code></td><td><code>30</code></td><td>Checks per user per minute. <code>0</code> removes the limit.</td></tr><tr><td><code>PACKAGE_CHECK_TIMEOUT_MS</code></td><td><code>10000</code></td><td>Time limit of one check.</td></tr></tbody></table><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>NPM_METADATA_TTL</code></td><td><code>300</code></td><td>Seconds npm metadata is considered fresh.</td></tr><tr><td><code>NPM_METADATA_STALE_TTL</code></td><td><code>3600</code></td><td>Seconds stale npm metadata may still be served while it is refreshed.</td></tr><tr><td><code>METADATA_TTL</code>, <code>METADATA_STALE_TTL</code></td><td>npm values</td><td>The same for the other ecosystems.</td></tr><tr><td><code>NPM_NEGATIVE_TTL</code>, <code>METADATA_NEGATIVE_TTL</code></td><td><code>60</code></td><td>Seconds a &quot;not found&quot; answer is cached.</td></tr><tr><td><code>NPM_MEMORY_CACHE_MB</code></td><td><code>128</code></td><td>In-process cache per replica. <code>0</code> turns it off.</td></tr><tr><td><code>FACTS_CACHE_TTL</code></td><td><code>86400</code></td><td>Seconds licenses and publish dates are cached.</td></tr><tr><td><code>OSV_CACHE_TTL</code></td><td><code>3600</code></td><td>Seconds vulnerability results are cached. A newly published vulnerability is enforced within this time.</td></tr></tbody></table><p>Shorter stale windows reduce Redis memory use. See <a href="/depgate/install/requirements#sizing">Requirements → Sizing</a>.</p><h2 id="artifact-cache" tabindex="-1">Artifact cache <a class="header-anchor" href="#artifact-cache" aria-label="Permalink to &quot;Artifact cache&quot;">​</a></h2><p>Package files from public registries, kept on each replica&#39;s local disk. See <a href="/depgate/admin/artifact-cache">Artifact cache</a>. Every variable except <code>ARTIFACT_CACHE_DIR</code> is a default: <strong>Settings → Artifact cache</strong> can change it at runtime.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ARTIFACT_CACHE_ENABLED</code></td><td><code>false</code> (<code>true</code> in every production setup in <code>deploy/</code>)</td><td>Turns the cache on. <strong>Settings → Artifact cache</strong> can switch it on or off and overrides this value.</td></tr><tr><td><code>ARTIFACT_CACHE_DIR</code></td><td><code>/var/lib/depgate/artifacts</code></td><td>Cache directory on local SSD. One directory per replica; never share it.</td></tr><tr><td><code>ARTIFACT_CACHE_MAX_SIZE_GB</code></td><td>none, required when enabled</td><td>Most disk the cache uses on each replica, in GB of 1024³ bytes. DepGate does not start when <code>ARTIFACT_CACHE_ENABLED</code> is <code>true</code> and no size is set here or in Settings. Never more than the disk&#39;s free space.</td></tr><tr><td><code>ARTIFACT_CACHE_MAX_FILES</code></td><td><code>200000</code></td><td>Most files on each replica.</td></tr><tr><td><code>ARTIFACT_CACHE_MAX_AGE_DAYS</code></td><td><code>30</code></td><td>Days after which a stored file is downloaded again. <code>0</code> turns it off.</td></tr><tr><td><code>ARTIFACT_CACHE_MAX_IDLE_DAYS</code></td><td><code>7</code></td><td>Days without a download after which a file is removed. <code>0</code> turns it off.</td></tr><tr><td><code>ARTIFACT_CACHE_MAX_FILE_MB</code></td><td><code>1024</code></td><td>Larger files are served but not stored.</td></tr></tbody></table><h2 id="data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>OSV_API_URL</code></td><td><code>https://api.osv.dev</code></td><td>Vulnerability data.</td></tr><tr><td><code>DEPS_DEV_ENABLED</code></td><td><code>true</code></td><td>Fill missing licenses and publish dates from deps.dev, for public packages only.</td></tr><tr><td><code>SCORECARD_ENABLED</code></td><td><code>true</code></td><td>OpenSSF Scorecard lookups for Project health policies. <code>false</code> makes those policies never match.</td></tr><tr><td><code>EPSS_ENABLED</code></td><td><code>true</code></td><td>Daily EPSS sync. <code>false</code> leaves every EPSS score unknown.</td></tr><tr><td><code>EPSS_FEED_URL</code></td><td>FIRST&#39;s daily file</td><td>Point it at an internal mirror for air-gapped installations.</td></tr><tr><td><code>EPSS_SYNC_INTERVAL_HOURS</code></td><td><code>24</code></td><td>How often EPSS syncs.</td></tr><tr><td><code>EPSS_STALE_AFTER_HOURS</code></td><td><code>72</code></td><td>When the interface warns that EPSS data is old.</td></tr><tr><td><code>MALICIOUS_FEED_URL</code>, <code>MALICIOUS_FEED_ARCHIVE_URL</code></td><td>the public feed</td><td>Source of the malware list. Point them at a mirror for air-gapped installations.</td></tr><tr><td><code>MALICIOUS_SYNC_INTERVAL_HOURS</code></td><td><code>1</code></td><td>Hours between malware feed syncs. <code>0</code> disables the schedule.</td></tr></tbody></table><h2 id="decision-ledger-audit-log-and-log-streaming" tabindex="-1">Decision Ledger, Audit Log and log streaming <a class="header-anchor" href="#decision-ledger-audit-log-and-log-streaming" aria-label="Permalink to &quot;Decision Ledger, Audit Log and log streaming&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>LEDGER_RETENTION_DAYS</code></td><td><code>180</code></td><td>How long Decision Ledger rows are kept. <code>0</code> keeps them forever.</td></tr><tr><td><code>AUDIT_RETENTION_DAYS</code></td><td><code>730</code></td><td>How long Audit Log entries are kept. <code>0</code> keeps them forever.</td></tr><tr><td><code>EVENT_STREAM_MAX_LEN</code></td><td><code>200000</code></td><td>Events kept for a log streaming destination that falls behind. Older events are lost beyond it.</td></tr></tbody></table><h2 id="webhooks-and-jobs" tabindex="-1">Webhooks and jobs <a class="header-anchor" href="#webhooks-and-jobs" aria-label="Permalink to &quot;Webhooks and jobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>WEBHOOK_COALESCE_SECONDS</code></td><td><code>300</code></td><td>Window in which identical <code>package_blocked</code> and <code>malware_requested</code> alerts are grouped. <code>0</code> sends each one.</td></tr><tr><td><code>WEBHOOK_MAX_ATTEMPTS</code></td><td><code>8</code></td><td>Attempts per webhook delivery.</td></tr><tr><td><code>WEBHOOK_BACKOFF_MS</code></td><td><code>30000</code></td><td>First retry delay; it doubles each attempt.</td></tr><tr><td><code>WEBHOOK_DELIVERY_RETENTION_DAYS</code></td><td><code>30</code></td><td>How long delivery history is kept.</td></tr><tr><td><code>WEBHOOK_DISABLE_AFTER_FAILURES</code></td><td><code>20</code></td><td>Consecutive failures before a webhook is turned off. <code>0</code> never.</td></tr></tbody></table><h2 id="monitoring-and-namespace-protection" tabindex="-1">Monitoring and namespace protection <a class="header-anchor" href="#monitoring-and-namespace-protection" aria-label="Permalink to &quot;Monitoring and namespace protection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>MONITOR_RETENTION_DAYS</code></td><td><code>90</code></td><td>A version nobody downloaded for this many days drops out of the monitoring report. <code>0</code> keeps everything.</td></tr><tr><td><code>MONITOR_MAX_ROWS_PER_POLICY</code></td><td><code>50000</code></td><td>Rows kept per monitoring policy.</td></tr><tr><td><code>NAMESPACE_COLLISION_INTERVAL_HOURS</code></td><td><code>24</code></td><td>How often the namespace collision check runs while it is turned on.</td></tr></tbody></table>',31)])])}const p=t(c,[["render",r]]);export{u as __pageData,p as default};
